{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "麻烦",
      "role": "CONTEXT",
      "explanation": "Polite request marker; it does not request an executable action, add parameters, or modify the order, so it does not alter authority."
    },
    {
      "text": "先",
      "role": "RELATION",
      "explanation": "Marks the forward movement as the first step in the ordered sequence; it does not itself execute an action."
    },
    {
      "text": "向前移动",
      "role": "ACTION",
      "explanation": "Requests one walk_forward action in the forward direction; its required distance is supplied by the following quantity span."
    },
    {
      "text": "4米",
      "role": "QUANTITY",
      "explanation": "Specifies 4 meters for the preceding walk_forward; 4 米 is positive and finite, so it legally parameterizes that action."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Comma separates the two clauses and marks a boundary between the ordered movement and the following stop, without adding an action."
    },
    {
      "text": "然后",
      "role": "RELATION",
      "explanation": "Marks the stop as the next action after the forward movement, establishing a single before/after relation."
    },
    {
      "text": "停住",
      "role": "ACTION",
      "explanation": "Requests one stop action with no parameters; it is the second and final step."
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "The source explicitly names two and only two executable actions: '向前移动' with distance '4米', and '停住'. There are no repeated, edited, or additional actions."
    },
    "action_order": {
      "status": "UNIQUE",
      "explanation": "The order markers '先' before the movement and '然后' before the stop resolve to one linear order: walk_forward(4m) then stop. No alternate ordering is left open."
    },
    "correction_scope": {
      "status": "UNIQUE",
      "explanation": "No edit, correction, override, replacement, or parameter-revision clause appears; there is no prior instruction whose scope could be changed. This dimension is inapplicable and introduces no alternative."
    },
    "repetition_scope": {
      "status": "UNIQUE",
      "explanation": "No repetition, again, or frequency expression appears; both actions occur once. This dimension is inapplicable and introduces no alternative."
    },
    "reference_resolution": {
      "status": "UNIQUE",
      "explanation": "There are no pronouns or ordinals requiring external context. '向前' fixes the direction of the movement, '4米' supplies its distance, and '先'/'然后' resolve the sequence to the two named actions."
    },
    "temporal_relations": {
      "status": "UNIQUE",
      "explanation": "The source expresses only a before/after sequence: complete the forward movement, then stop. There is no simultaneity, waiting, or completion condition beyond the linear predecessor relation, which is representable as s1 walk_forward then s2 stop."
    },
    "unresolved_relations": {
      "status": "UNIQUE",
      "explanation": "The source leaves no choice, scope, ordering, or relationship explicitly unresolved; none of the clauses offers an alternate relation."
    }
  }
}
